const cache = new Map();

function remember(key) {
  if (cache.has(key)) {
    return "hit";
  }
  if (cache.size === 2) {
    const [oldest] = cache.keys();
    cache.delete(oldest);
  }
  cache.set(key, true);
  return "miss";
}

console.log(["a", "b", "a", "c", "a", "b"].map(remember).join(","));
console.log([...cache.keys()].join(","));
